program.compute:
options=read('/input/options')
goal_min=goal['min_count']
goal_max=goal['max_count']
goal_sum_bounds=goal.get('sum_bounds',{})
goal_unique=goal.get('unique',[])
goal_order=goal.get('order_by',[])

from itertools import combinations

result=None

for k in range(goal_min,goal_max+1):
 for combo in combinations(options,k):
  ids=[opt['id'] for opt in combo]
  owners=[opt['owner'] for opt in combo]
  # unique owners
  if len(set(owners))!=len(owners):
   continue
  # sum bounds
  valid_sum=True
  for field,bounds in goal_sum_bounds.items():
   s=sum(opt.get(field,0) for opt in combo)
   if 'min' in bounds and s<bounds['min']:
    valid_sum=False
    break
   if 'max' in bounds and s>bounds['max']:
    valid_sum=False
    break
  if not valid_sum:
   continue
  # no conflicts
  if goal.get('no_conflicts',False):
   conflict_found=False
   for i in range(len(combo)):
    for j in range(i+1,len(combo)):
     if combo[j]['id'] in combo[i].get('conflicts',[]) or combo[i]['id'] in combo[j].get('conflicts',[]):
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # closed dependencies
  if goal.get('closed_dependencies',False):
   all_reqs_met=True
   selected_ids=set(ids)
   for opt in combo:
    for req in opt.get('requires',[]):
     if req not in selected_ids:
      all_reqs_met=False
      break
    if not all_reqs_met:
     break
   if not all_reqs_met:
    continue
  # cover fields
  cover=goal.get('cover',{})
  cover_ok=True
  for field,vals in cover.items():
   vals_set=set(vals)
   found_vals=set()
   for opt in combo:
    v=opt.get(field,None)
    if isinstance(v,list):
     found_vals.update(v)
    else:
     found_vals.add(v)
   if not vals_set.issubset(found_vals):
    cover_ok=False
    break
  if not cover_ok:
   continue
  # order by
  sorted_combo=sorted(combo,key=lambda x: tuple(x.get(f) for f in goal_order))
  sorted_ids=[opt['id'] for opt in sorted_combo]
  if ids!=sorted_ids:
   continue
  # valid check
  if valid(ids):
   result=ids
   break
 if result is not None:
  break

program.effects:
if result is not None:
 write('/output/selection',result)
 send('report','team',result)
 if exists('/tmp/cache'):
  delete('/tmp/cache')
else:
 # no valid selection found
 pass

